 const valid=['X','Y','Z'].every(a=>{const n=Number($('import'+a).value);return Number.isInteger(n)&&n>=1&&n<=10;});
 const colours=!$('customImportBlocks').checked||$('importBlue').checked||$('importYellow').checked;
