 if(!pendingModel||!$('modelDialog').open)return;conversionRunning=true;conversionQueued=false;
 try{await performModelConversion();}catch(e){$('modelReport').textContent='Preview could not update: '+e.message;$('convertModel').hidden=false;throw e;}
