async function exportPlayPack(book){
 const ids=library.filter(p=>p.collection===book.name).map(p=>p.id);
 if(!ids.length)throw Error('Save a puzzle in this book first.');
 const result=await task('Preparing book...',()=>api('book-export',{ids}));
 if(window.chrome?.webview)window.chrome.webview.postMessage({type:'savePackage',file:result.file});
 else {
  const response=await fetch('/api/export/'+encodeURIComponent(result.file),{headers:{'X-Studio-Token':token}});
  if(!response.ok)throw Error('The book could not be downloaded.');
  const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');
  link.href=url;link.download=book.name+'.pictobook';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
 toast(result.message);
}
function showPuzzleMenu(item,e){openMenu([['Delete puzzle',()=>deleteItem('puzzle',item)]],e);}
async function deleteItem(kind,item){
 if(kind==='book'&&books.length<=1)throw Error('Keep at least one book in your library.');
 const title=kind==='book'?'Delete book and its puzzles?':'Delete puzzle?';
 const dialog=document.createElement('dialog');dialog.innerHTML='<h2></h2><p></p><div class="model-actions"><button class="button">Cancel</button><button class="button primary">Delete</button></div>';dialog.querySelector('h2').textContent=title;dialog.querySelector('p').textContent=item.name+' will be moved to the local deleted-items folder.';document.body.append(dialog);
 const yes=await new Promise(resolve=>{dialog.querySelectorAll('button')[0].onclick=()=>resolve(false);dialog.querySelectorAll('button')[1].onclick=()=>resolve(true);dialog.oncancel=()=>resolve(false);dialog.showModal();});dialog.close();dialog.remove();if(!yes)return;
 const result=await api('delete',{kind,id:item.id,name:item.name});books=result.books;library=result.library;selectedBooks.delete(item.name);renderLibrary();$('libraryCount').textContent=library.length;if((kind==='puzzle'&&doc.id===item.id)||(kind==='book'&&doc.collection===item.name)){clearTimeout(saveTimer);dirty=false;if(library.length)loadDocument(library[0]);else loadDocument({format:'voxel-studio-1',name:'New puzzle',collection:books[0]?.name||'Custom Puzzles',description:'',dimensions:[6,6,6],cells:[]});setPage('library');}toast('Moved to deleted items.');
}
function fitModelCamera(direction='iso',reposition=true){
 if(reposition&&$('freeRotateModel').checked&&pendingModel&&modelContent){const position=modelCamera.position.clone(),quaternion=modelCamera.quaternion.clone(),up=modelCamera.up.clone(),target=modelControls.target.clone(),distance=position.distanceTo(target);fitModelCamera(direction,false);const rotation=quaternion.clone().multiply(modelCamera.quaternion.clone().invert()).multiply(pendingModel.originalPose.quaternion).multiply(pendingModel.object.quaternion.clone().invert()),scale=distance/Math.max(.001,modelCamera.position.distanceTo(modelControls.target));applyPositioningRotation(rotation);pendingModel.object.scale.multiplyScalar(scale);if(modelContent!==pendingModel.object)modelContent.scale.multiplyScalar(scale);modelCamera.position.copy(position);modelCamera.quaternion.copy(quaternion);modelCamera.up.copy(up);modelControls.target.copy(target);modelControls.update();positioningChanged();return;}
 if(!modelContent)return;const box=new THREE.Box3().setFromObject(modelContent),centre=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),distance=Math.max(size.length()/2,.01)/Math.sin(THREE.MathUtils.degToRad(19))*1.1;
 const offsets={front:[0,0,1],back:[0,0,-1],top:[0,1,0],bottom:[0,-1,0],left:[-1,0,0],side:[1,0,0],iso:[1.35,1.1,1.55]};modelCamera.up.set(0,1,0);if(direction==='top'||direction==='bottom')modelCamera.up.set(0,0,direction==='top'?-1:1);modelControls.target.copy(centre);modelCamera.position.copy(centre).addScaledVector(new THREE.Vector3(...offsets[direction]).normalize(),distance);modelCamera.lookAt(centre);modelControls.update();
}
