 function pin(value){document.body.dataset.menuPinned=String(value);localStorage.setItem('pictoMenuPinned',String(value));$('pinSidebar').setAttribute('aria-pressed',String(value));$('pinSidebar').innerHTML=uiIcon('pin')+(value?'Unpin menu':'Keep open');menu(value);}
