 sidebar.onmouseenter=()=>{clearTimeout(menuTimer);menu(true);};sidebar.onmouseleave=()=>{menuTimer=setTimeout(()=>menu(false),200);};
 sidebar.addEventListener('focusin',()=>{if(keyboardNavigation)menu(true);});sidebar.addEventListener('focusout',()=>setTimeout(()=>{if(!sidebar.contains(document.activeElement))menu(false);},0));
